<?php require_once __DIR__.'/includes/bootstrap.php';require_role('customer');if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;}check_csrf();$sid=filter_input(INPUT_POST,'service_id',FILTER_VALIDATE_INT);$pdo=db();try{$pdo->beginTransaction();$s=$pdo->prepare('SELECT id,business_id FROM services WHERE id=? AND is_active=1 FOR UPDATE');$s->execute([$sid]);$service=$s->fetch();if(!$service)throw new RuntimeException('Service unavailable.');$lock=$pdo->prepare('SELECT id FROM businesses WHERE id=? FOR UPDATE');$lock->execute([$service['business_id']]);$n=$pdo->prepare('SELECT COALESCE(MAX(daily_number),0)+1 FROM queue_tickets WHERE business_id=? AND ticket_date=?');$n->execute([$service['business_id'],date('Y-m-d')]);$num=(int)$n->fetchColumn();$code='Q'.date('ymd').'-'.str_pad((string)$num,3,'0',STR_PAD_LEFT);$i=$pdo->prepare("INSERT INTO queue_tickets(ticket_code,customer_user_id,business_id,service_id,ticket_date,daily_number,status) VALUES(?,?,?,?,?,?,'WAITING')");$i->execute([$code,$_SESSION['user_id'],$service['business_id'],$sid,date('Y-m-d'),$num]);$id=$pdo->lastInsertId();$ev=$pdo->prepare("INSERT INTO queue_events(ticket_id,actor_user_id,event_type) VALUES(?,?,'JOINED')");$ev->execute([$id,$_SESSION['user_id']]);$pdo->commit();header('Location: ticket.php?id='.$id);exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();notice($e instanceof RuntimeException?$e->getMessage():'Could not create ticket.','error');header('Location: customer.php');exit;}